import json, pathlib, subprocess, sys
key='canario-routing-ada-369716520'
def count(path):
 rows=[]
 for line in pathlib.Path(path).read_text().splitlines():
  try: row=json.loads(line)
  except json.JSONDecodeError: continue
  if row.get('idempotency_key')==key and row.get('from')=='NEXUS' and row.get('to')=='ADA': rows.append(row)
 return len(rows)
services=all(subprocess.run(['systemctl','--user','is-active','--quiet',unit]).returncode==0 for unit in ('seal-chat.service','ada-codex-remote-bridge.service'))
ada=count('messages/terminal_log.jsonl')
jarvis=count('messages/vscode_commands.jsonl')
ok=services and ada==1 and jarvis==0
print(f'DELIVERY_OK ada={ada} jarvis={jarvis}' if ok else f'DELIVERY_FAIL services={services} ada={ada} jarvis={jarvis}')
sys.exit(0 if ok else 1)
